def model_lin(th, form):
    c,a,b,d=th
    if form==0: g=t**a; h=P**b*np.exp(-d*P)
    elif form==1: g=np.exp(-d*t)*t**a; h=P**b
    elif form==2: g=t**a; h=P**b*np.exp(-d*P)  
    elif form==3: g=np.exp(-d*t); h=P**b
    elif form==4: g=np.exp(a*t); h=P**b*np.exp(-d*P)
    return g*h
def resid(th,form):
    c=th[0]
    X=np.column_stack([np.sqrt(P),t**c,model_lin(th,form)])
    coef,*_=np.linalg.lstsq(X,y,rcond=None)
    return y-X@coef
