import numpy as np
from scipy.optimize import least_squares
t=df['t'];P=df['P'];y=df['dP_dt']
rng=np.random.default_rng(0)
def model_lin(th, form):
    c,a,b,d=th
    if form==0: return t**a*P**b*np.exp(-d*P)
    if form==1: return np.exp(-d*t)*t**a*P**b
    if form==2: return np.exp(a*t)*P**b*np.exp(-d*P)
    if form==3: return np.exp(-d*t)*P**b
    if form==4: return np.sin(a*t)*P**b*np.exp(-d*P)
def resid(th,form):
    c=th[0]
    with np.errstate(all='ignore'):
        X=np.column_stack([np.sqrt(P),t**c,model_lin(th,form)])
        coef,*_=np.linalg.lstsq(X,y,rcond=None)
        r=y-X@coef
    return np.nan_to_num(r,nan=1e3,posinf=1e3,neginf=-1e3)
